'use client';

import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  useReactTable,
  getCoreRowModel,
  getSortedRowModel,
  getFilteredRowModel,
  getPaginationRowModel,
  getExpandedRowModel,
  ColumnDef,
  ColumnFiltersState,
  ColumnOrderState,
  ColumnPinningState,
  ColumnSizingState,
  ExpandedState,
  PaginationState,
  Row,
  RowSelectionState,
  SortingState,
  Table,
  Updater,
  VisibilityState,
} from '@tanstack/react-table';
import { ChevronDown, ChevronRight } from 'lucide-react';
import { cn } from '../../lib/utils';
import { Checkbox } from '../ui/checkbox';
import {
  CellRange,
  DataGridContextValue,
  DataGridDensity,
  DataGridProps,
  FocusedCell,
  META_COLUMN_IDS,
  isInteractiveTarget,
  isMetaColumn,
  normalizeCellRange,
} from './types';
import { DataGridContext } from './context';
import { DataGridHeader } from './data-grid-header';
import { DataGridBody } from './data-grid-body';
import { DataGridPagination } from './data-grid-pagination';
import { DataGridActionDock } from './data-grid-action-dock';
import { DataGridFilters } from './data-grid-filters';
import { mergeLabels } from './labels';
import { copySelectionAsTSV } from './export-utils';

function useControllable<T>(
  controlled: T | undefined,
  defaultValue: T,
  onChange?: (next: T) => void
): [T, (updater: Updater<T>) => void] {
  const [internal, setInternal] = useState<T>(defaultValue);
  const isControlled = controlled !== undefined;
  const value = isControlled ? (controlled as T) : internal;

  const set = useCallback(
    (updater: Updater<T>) => {
      const next = typeof updater === 'function' ? (updater as (old: T) => T)(value) : updater;
      if (Object.is(next, value)) return;
      if (!isControlled) setInternal(next);
      onChange?.(next);
    },
    [isControlled, onChange, value]
  );

  return [value, set];
}

export function DataGrid<TData>(props: DataGridProps<TData>) {
  const {
    data,
    columns,
    getRowId: userGetRowId,

    // Selection
    enableRowSelection = false,
    enableMultiRowSelection = true,
    rowSelection: rowSelectionProp,
    defaultRowSelection,
    onRowSelectionChange,
    onRowSelectionStateChange,

    // Actions
    actions = [],
    dockOptions,

    // Context menus
    cellContextMenuItems,
    headerContextMenuItems,
    enableCellContextMenu = false,
    enableHeaderContextMenu = false,

    // Pagination
    enablePagination = true,
    pageSize = 10,
    pageSizeOptions = [10, 20, 50, 100],
    manualPagination = false,
    pageCount,
    totalCount,
    pagination: paginationProp,
    onPaginationChange,

    // Sorting
    enableSorting = true,
    enableMultiSort = false,
    manualSorting = false,
    sorting: sortingProp,
    defaultSorting,
    onSortingChange,

    // Filtering
    enableGlobalFilter = true,
    enableColumnFilters = true,
    manualFiltering = false,
    globalFilter: globalFilterProp,
    defaultGlobalFilter,
    columnFilters: columnFiltersProp,
    defaultColumnFilters,
    onGlobalFilterChange,
    onColumnFiltersChange,

    // Visibility / sizing / pinning / order
    columnVisibility: columnVisibilityProp,
    defaultColumnVisibility,
    onColumnVisibilityChange,

    columnSizing: columnSizingProp,
    defaultColumnSizing,
    onColumnSizingChange,

    enableColumnPinning = false,
    columnPinning: columnPinningProp,
    defaultColumnPinning,
    onColumnPinningChange,

    enableColumnReordering = false,
    columnOrder: columnOrderProp,
    defaultColumnOrder,
    onColumnOrderChange,

    // Server
    onDataChange,
    serverDebounceMs = 300,

    // Editing
    enableCellEditing = false,
    defaultEditMode = 'click',
    onCellEdit,
    onCellValueChange,
    onCellEditError,

    // Resizing
    enableColumnResizing = true,

    // Virtualization
    enableVirtualization = false,
    estimateSize = 35,

    // Expansion
    enableRowExpansion = false,
    renderExpandedRow,
    getRowCanExpand,
    expanded: expandedProp,
    defaultExpanded,
    onExpandedChange,

    // Row interactions
    onRowClick,
    onRowDoubleClick,
    rowClassName,

    // Cell selection
    enableCellSelection = false,

    // Keyboard nav
    enableKeyboardNavigation = true,

    // Density
    density: densityProp,
    defaultDensity = 'normal',
    onDensityChange,
    enableDensityToggle = false,

    // Export
    enableExport = false,
    exportFileName,

    // Layout
    maxHeight,
    stickyHeader = false,

    // States
    isLoading = false,
    error = null,
    loadingRowCount = 5,
    emptyState,
    loadingState,
    errorState,

    // i18n
    labels: labelsProp,

    className,
    'aria-label': ariaLabel = 'Data grid',
    'aria-describedby': ariaDescribedBy,
  } = props;

  const labels = useMemo(() => mergeLabels(labelsProp), [labelsProp]);

  // ---------------- Controlled / uncontrolled state ----------------

  // Dev-time check: controlled selection requires a state-change callback so the
  // parent can actually update the value it owns.
  if (
    import.meta.env.DEV &&
    rowSelectionProp !== undefined &&
    !onRowSelectionStateChange
  ) {
    // eslint-disable-next-line no-console
    console.warn(
      '[DataGrid] You passed a controlled `rowSelection` prop without `onRowSelectionStateChange`. ' +
        'User interactions will not update the value because the consumer owns it. ' +
        'Pass `onRowSelectionStateChange` to receive the next RowSelectionState.'
    );
  }

  const [rowSelection, setRowSelection] = useControllable<RowSelectionState>(
    rowSelectionProp,
    defaultRowSelection ?? {},
    onRowSelectionStateChange
  );
  const [sorting, setSorting] = useControllable<SortingState>(
    sortingProp,
    defaultSorting ?? [],
    onSortingChange
  );
  const [columnFilters, setColumnFilters] = useControllable<ColumnFiltersState>(
    columnFiltersProp,
    defaultColumnFilters ?? [],
    onColumnFiltersChange
  );
  const [globalFilter, setGlobalFilter] = useControllable<string>(
    globalFilterProp,
    defaultGlobalFilter ?? '',
    onGlobalFilterChange
  );
  const [columnVisibility, setColumnVisibility] = useControllable<VisibilityState>(
    columnVisibilityProp,
    defaultColumnVisibility ?? {},
    onColumnVisibilityChange
  );
  const [columnSizing, setColumnSizing] = useControllable<ColumnSizingState>(
    columnSizingProp,
    defaultColumnSizing ?? {},
    onColumnSizingChange
  );
  const [columnPinning, setColumnPinning] = useControllable<ColumnPinningState>(
    columnPinningProp,
    defaultColumnPinning ?? { left: [], right: [] },
    onColumnPinningChange
  );
  const [columnOrder, setColumnOrder] = useControllable<ColumnOrderState>(
    columnOrderProp,
    defaultColumnOrder ?? [],
    onColumnOrderChange
  );
  const [pagination, setPagination] = useControllable<PaginationState>(
    paginationProp,
    { pageIndex: 0, pageSize },
    onPaginationChange
  );
  const [expanded, setExpanded] = useControllable<ExpandedState>(
    expandedProp,
    defaultExpanded ?? {},
    onExpandedChange
  );
  const [density, setDensity] = useControllable<DataGridDensity>(densityProp, defaultDensity, onDensityChange);

  const tableRef = useRef<Table<TData> | null>(null);

  // ---------------- Editing state ----------------

  const [editingCell, setEditingCell] = useState<{ rowId: string; columnId: string } | null>(null);

  // ---------------- Focus + range selection state ----------------

  const [focusedCell, setFocusedCell] = useState<FocusedCell | null>(null);
  const [cellRange, setCellRange] = useState<CellRange | null>(null);

  // ---------------- Enhanced columns: select + expand ----------------

  const enhancedColumns = useMemo(() => {
    const cols: ColumnDef<TData, any>[] = [];

    if (enableRowExpansion) {
      cols.push({
        id: META_COLUMN_IDS.expand,
        header: () => null,
        cell: ({ row }: { row: Row<TData> }) => {
          if (!row.getCanExpand()) return null;
          const isExpanded = row.getIsExpanded();
          return (
            <button
              type='button'
              onClick={(e) => {
                e.stopPropagation();
                row.toggleExpanded();
              }}
              aria-label={isExpanded ? labels.collapseRow : labels.expandRow}
              className='inline-flex items-center justify-center h-6 w-6 rounded hover:bg-muted/70'>
              {isExpanded ? <ChevronDown className='h-4 w-4' /> : <ChevronRight className='h-4 w-4' />}
            </button>
          );
        },
        enableSorting: false,
        enableHiding: false,
        enableResizing: false,
        size: 36,
      });
    }

    if (enableRowSelection) {
      cols.push({
        id: META_COLUMN_IDS.select,
        header: ({ table }: { table: Table<TData> }) => {
          const isAll = table.getIsAllPageRowsSelected();
          const isSome = table.getIsSomePageRowsSelected();
          return (
            <div className='flex items-center justify-center'>
              <Checkbox
                checked={isAll}
                indeterminate={!isAll && isSome}
                onCheckedChange={(checked) => {
                  table.toggleAllPageRowsSelected(Boolean(checked));
                }}
                aria-label={labels.selectAll}
                className='size-3.5'
              />
            </div>
          );
        },
        cell: ({ row }: { row: Row<TData> }) => (
          <div className='flex items-center justify-center' onClick={(e) => e.stopPropagation()}>
            <Checkbox
              checked={row.getIsSelected()}
              onCheckedChange={(checked) => row.toggleSelected(Boolean(checked))}
              aria-label={labels.selectRow(row.index)}
              className='size-3.5'
            />
          </div>
        ),
        enableSorting: false,
        enableHiding: false,
        enableResizing: false,
        size: 44,
      });
    }

    for (const col of columns) {
      cols.push(col as unknown as ColumnDef<TData, any>);
    }

    return cols;
  }, [columns, enableRowSelection, enableRowExpansion, labels]);

  // ---------------- TanStack Table ----------------

  const table = useReactTable<TData>({
    data,
    columns: enhancedColumns,
    state: {
      rowSelection,
      sorting,
      columnFilters,
      columnVisibility,
      columnSizing,
      columnPinning,
      columnOrder,
      globalFilter,
      pagination,
      expanded,
    },
    enableRowSelection,
    enableMultiRowSelection,
    enableMultiSort,
    enableColumnResizing,
    enableColumnPinning,
    enableExpanding: enableRowExpansion,
    columnResizeMode: 'onChange',
    onRowSelectionChange: setRowSelection,
    onSortingChange: setSorting,
    onColumnFiltersChange: setColumnFilters,
    onColumnVisibilityChange: setColumnVisibility,
    onColumnSizingChange: setColumnSizing,
    onColumnPinningChange: setColumnPinning,
    onColumnOrderChange: setColumnOrder,
    onGlobalFilterChange: setGlobalFilter,
    onPaginationChange: setPagination,
    onExpandedChange: setExpanded,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: enableSorting ? getSortedRowModel() : undefined,
    getFilteredRowModel: enableGlobalFilter || enableColumnFilters ? getFilteredRowModel() : undefined,
    getPaginationRowModel: enablePagination ? getPaginationRowModel() : undefined,
    getExpandedRowModel: enableRowExpansion ? getExpandedRowModel() : undefined,
    getRowCanExpand: enableRowExpansion ? getRowCanExpand ?? (() => true) : undefined,
    manualPagination,
    manualSorting,
    manualFiltering,
    pageCount: manualPagination ? (pageCount ?? -1) : undefined,
    meta: { totalCount },
    getRowId:
      userGetRowId ??
      ((row, index) => {
        const id = (row as any)?.id;
        return id != null ? String(id) : String(index);
      }),
  });

  tableRef.current = table;

  // ---------------- Row-selection rich callback (provides Row objects) ----------------
  // Kept as an effect because the consumer needs Row instances, which the table only
  // resolves after re-rendering with the new selection state.
  const onRowSelectionChangeRef = useRef(onRowSelectionChange);
  onRowSelectionChangeRef.current = onRowSelectionChange;

  useEffect(() => {
    const cb = onRowSelectionChangeRef.current;
    if (!cb) return;
    const rows = table.getFilteredSelectedRowModel().rows;
    cb(rows, rowSelection);
  }, [rowSelection, table]);

  // ---------------- Server-side data change with debounce ----------------

  const onDataChangeRef = useRef(onDataChange);
  onDataChangeRef.current = onDataChange;

  const lastSentRef = useRef<{
    pageIndex: number;
    pageSize: number;
    sorting: SortingState;
    columnFilters: ColumnFiltersState;
    globalFilter: string;
  } | null>(null);
  useEffect(() => {
    const cb = onDataChangeRef.current;
    if (!cb) return;
    if (!manualPagination && !manualSorting && !manualFiltering) return;

    const prev = lastSentRef.current;
    const next = {
      pageIndex: pagination.pageIndex,
      pageSize: pagination.pageSize,
      sorting,
      columnFilters,
      globalFilter,
    };

    if (
      prev &&
      prev.pageIndex === next.pageIndex &&
      prev.pageSize === next.pageSize &&
      prev.sorting === next.sorting &&
      prev.columnFilters === next.columnFilters &&
      prev.globalFilter === next.globalFilter
    ) {
      return;
    }

    // Debounce only the global filter typing — pagination/sort/column-filters fire immediately
    const onlyGlobalChanged =
      prev &&
      prev.pageIndex === next.pageIndex &&
      prev.pageSize === next.pageSize &&
      prev.sorting === next.sorting &&
      prev.columnFilters === next.columnFilters &&
      prev.globalFilter !== next.globalFilter;

    const delay = onlyGlobalChanged ? serverDebounceMs : 0;

    const handle = window.setTimeout(() => {
      lastSentRef.current = next;
      cb({
        pagination: { pageIndex: next.pageIndex, pageSize: next.pageSize },
        sorting: next.sorting.map((s) => ({ id: s.id, desc: s.desc })),
        filters: next.columnFilters.map((f) => ({ id: f.id, value: f.value })),
        globalFilter: next.globalFilter,
      });
    }, delay);

    return () => window.clearTimeout(handle);
  }, [
    pagination.pageIndex,
    pagination.pageSize,
    sorting,
    columnFilters,
    globalFilter,
    manualPagination,
    manualSorting,
    manualFiltering,
    serverDebounceMs,
  ]);

  // ---------------- Selected rows ----------------

  const selectedRows = useMemo(
    () => table.getFilteredSelectedRowModel().rows,
    // intentionally key on rowSelection so we re-evaluate
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [rowSelection, table]
  );

  // ---------------- Ctrl+C — copy selected rows or range as TSV ----------------

  const cellRangeRef = useRef(cellRange);
  cellRangeRef.current = cellRange;
  const selectedRowsRef = useRef(selectedRows);
  selectedRowsRef.current = selectedRows;

  useEffect(() => {
    if (!enableCellSelection && !enableRowSelection) return;
    const handler = (e: KeyboardEvent) => {
      if (!(e.ctrlKey || e.metaKey) || e.key !== 'c') return;
      if (isInteractiveTarget(e.target)) return;
      const range = cellRangeRef.current;
      const selected = selectedRowsRef.current;
      // Range first
      if (range) {
        const visibleCols = table.getVisibleLeafColumns().filter((c) => !isMetaColumn(c.id));
        const rows = table.getRowModel().rows;
        const { r1, r2, c1, c2 } = normalizeCellRange(range);
        const matrix: any[][] = [];
        for (let r = r1; r <= r2 && r < rows.length; r++) {
          const row = rows[r];
          const line: any[] = [];
          for (let c = c1; c <= c2 && c < visibleCols.length; c++) {
            line.push(row.getValue(visibleCols[c].id));
          }
          matrix.push(line);
        }
        if (matrix.length > 0) {
          copySelectionAsTSV(matrix);
          e.preventDefault();
          return;
        }
      }
      // Else: selected rows
      if (selected.length > 0) {
        const visibleCols = table.getVisibleLeafColumns().filter((c) => !isMetaColumn(c.id));
        const matrix = selected.map((row) => visibleCols.map((c) => row.getValue(c.id)));
        copySelectionAsTSV(matrix);
        e.preventDefault();
      }
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [enableCellSelection, enableRowSelection, table]);

  // ---------------- Context value ----------------

  const contextValue: DataGridContextValue<TData> = useMemo(
    () => ({
      table,
      selectedRows,
      actions,
      cellContextMenuItems,
      headerContextMenuItems,
      enableCellContextMenu,
      enableHeaderContextMenu,
      enableCellEditing,
      defaultEditMode,
      editingCell,
      setEditingCell,
      onCellEdit,
      onCellValueChange,
      onCellEditError,
      isLoading,
      error,
      labels,
      density,
      enableColumnPinning,
      enableColumnReordering,
      enableRowExpansion,
      renderExpandedRow,
      enableCellSelection,
      enableKeyboardNavigation,
      focusedCell,
      setFocusedCell,
      cellRange,
      setCellRange,
      rowClassName,
      onRowClick,
      onRowDoubleClick,
      loadingRowCount,
      emptyState,
      loadingState,
      errorState,
    }),
    [
      table,
      selectedRows,
      actions,
      cellContextMenuItems,
      headerContextMenuItems,
      enableCellContextMenu,
      enableHeaderContextMenu,
      enableCellEditing,
      defaultEditMode,
      editingCell,
      onCellEdit,
      onCellValueChange,
      onCellEditError,
      isLoading,
      error,
      labels,
      density,
      enableColumnPinning,
      enableColumnReordering,
      enableRowExpansion,
      renderExpandedRow,
      enableCellSelection,
      enableKeyboardNavigation,
      focusedCell,
      cellRange,
      rowClassName,
      onRowClick,
      onRowDoubleClick,
      loadingRowCount,
      emptyState,
      loadingState,
      errorState,
    ]
  );

  // ---------------- aria-rowcount: total rows + 1 (header) ----------------

  const totalRowsForAria =
    manualPagination && totalCount != null ? totalCount : table.getFilteredRowModel().rows.length;

  const tableContainerStyle: React.CSSProperties = {};
  if (maxHeight !== undefined) tableContainerStyle.maxHeight = maxHeight;

  return (
    <DataGridContext.Provider value={contextValue}>
      <div
        className={cn('space-y-4', className)}
        role='region'
        aria-label={ariaLabel}
        aria-describedby={ariaDescribedBy}
        data-density={density}>
        {(enableGlobalFilter || enableColumnFilters || enableDensityToggle || enableExport) && (
          <DataGridFilters
            enableGlobalFilter={enableGlobalFilter}
            globalFilter={globalFilter}
            onGlobalFilterChange={setGlobalFilter}
            enableDensityToggle={enableDensityToggle}
            density={density}
            onDensityChange={(d) => setDensity(d)}
            enableExport={enableExport}
            exportFileName={exportFileName}
          />
        )}

        <div className='rounded-md border border-border bg-background'>
          <div
            className={cn('relative overflow-auto', stickyHeader && 'overflow-y-auto')}
            style={tableContainerStyle}>
            <table
              className='w-full caption-bottom text-sm border-collapse'
              role='grid'
              aria-rowcount={totalRowsForAria + 1}
              style={{ width: table.getCenterTotalSize() + table.getLeftTotalSize() + table.getRightTotalSize() }}>
              <DataGridHeader stickyHeader={stickyHeader} />
              <DataGridBody enableVirtualization={enableVirtualization} estimateSize={estimateSize} />
            </table>
          </div>
        </div>

        {enablePagination && <DataGridPagination pageSizeOptions={pageSizeOptions} />}
      </div>

      {enableRowSelection && selectedRows.length > 0 && actions.length > 0 && (
        <DataGridActionDock dockOptions={dockOptions} />
      )}
    </DataGridContext.Provider>
  );
}

'use client';

import React, { useState } from 'react';
import { flexRender } from '@tanstack/react-table';
import { ArrowUpDown, ArrowUp, ArrowDown, GripVertical } from 'lucide-react';
import { cn } from '../../lib/utils';
import { useDataGrid } from './context';
import { HeaderContextMenu } from './data-grid-context-menu';
import { ColumnFilter } from './column-filter';
import { getPinningStyles, isMetaColumn } from './types';

interface DataGridHeaderProps {
  stickyHeader?: boolean;
}

export function DataGridHeader({ stickyHeader = false }: DataGridHeaderProps) {
  const {
    table,
    headerContextMenuItems,
    enableHeaderContextMenu,
    enableColumnReordering,
    labels,
  } = useDataGrid();

  const [dragColId, setDragColId] = useState<string | null>(null);

  const handleDragStart = (e: React.DragEvent, columnId: string) => {
    if (!enableColumnReordering) return;
    if (isMetaColumn(columnId)) return;
    setDragColId(columnId);
    e.dataTransfer.effectAllowed = 'move';
    try {
      e.dataTransfer.setData('text/plain', columnId);
    } catch {
      // ignore
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    if (!enableColumnReordering || !dragColId) return;
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  };

  const handleDrop = (e: React.DragEvent, targetColumnId: string) => {
    if (!enableColumnReordering || !dragColId) return;
    e.preventDefault();
    if (dragColId === targetColumnId) {
      setDragColId(null);
      return;
    }
    const order = table.getState().columnOrder.length
      ? [...table.getState().columnOrder]
      : table.getAllLeafColumns().map((c) => c.id);
    const fromIdx = order.indexOf(dragColId);
    const toIdx = order.indexOf(targetColumnId);
    if (fromIdx === -1 || toIdx === -1) {
      setDragColId(null);
      return;
    }
    order.splice(fromIdx, 1);
    order.splice(toIdx, 0, dragColId);
    table.setColumnOrder(order);
    setDragColId(null);
  };

  return (
    <thead
      className={cn(
        '[&_tr]:border-b bg-muted/30',
        stickyHeader && 'sticky top-0 z-10 backdrop-blur-sm bg-background/95'
      )}>
      {table.getHeaderGroups().map((headerGroup) => (
        <tr key={headerGroup.id} role='row'>
          {headerGroup.headers.map((header) => {
            const canSort = header.column.getCanSort();
            const sortDirection = header.column.getIsSorted();
            const filterConfig = (header.column.columnDef as any).filter;
            const showFilter = filterConfig && header.column.getCanFilter();
            const isDragSource = dragColId === header.column.id;
            const reorderable = enableColumnReordering && !isMetaColumn(header.column.id);
            const pinned = header.column.getIsPinned();

            const headerContent = (
              <th
                role='columnheader'
                aria-sort={
                  sortDirection === 'asc'
                    ? 'ascending'
                    : sortDirection === 'desc'
                    ? 'descending'
                    : canSort
                    ? 'none'
                    : undefined
                }
                draggable={reorderable}
                onDragStart={(e) => handleDragStart(e, header.column.id)}
                onDragOver={handleDragOver}
                onDrop={(e) => handleDrop(e, header.column.id)}
                onDragEnd={() => setDragColId(null)}
                className={cn(
                  'h-10 px-3 text-left align-middle font-medium text-foreground text-sm relative border-r border-border/50 bg-muted/30',
                  '[&:has([role=checkbox])]:pr-0',
                  isMetaColumn(header.column.id) && 'border-r-0',
                  header.column.getIsResizing() && 'border-r-primary',
                  isDragSource && 'opacity-50',
                  pinned === 'left' && 'shadow-[2px_0_0_0_var(--border)]',
                  pinned === 'right' && 'shadow-[-2px_0_0_0_var(--border)]'
                )}
                style={{
                  width: header.getSize(),
                  minWidth: header.column.columnDef.minSize ?? 50,
                  maxWidth: header.column.columnDef.maxSize ?? 500,
                  ...getPinningStyles(header.column, 2),
                }}>
                <div className='flex items-center gap-1.5'>
                  {reorderable && (
                    <span
                      className='cursor-grab active:cursor-grabbing text-muted-foreground/40 hover:text-muted-foreground'
                      aria-hidden='true'>
                      <GripVertical className='h-3.5 w-3.5' />
                    </span>
                  )}

                  <button
                    type='button'
                    disabled={!canSort}
                    onClick={(e) => {
                      if (e.button !== 0) return;
                      const handler = header.column.getToggleSortingHandler();
                      if (handler) handler(e);
                    }}
                    onMouseDown={(e) => {
                      if (e.button !== 0) e.stopPropagation();
                    }}
                    className={cn(
                      'flex-1 flex items-center gap-1 text-left bg-transparent border-0 outline-none p-0 m-0',
                      canSort && 'cursor-pointer hover:text-foreground'
                    )}>
                    <span className='flex-1 truncate'>
                      {header.isPlaceholder
                        ? null
                        : flexRender(header.column.columnDef.header, header.getContext())}
                    </span>
                    {canSort && (
                      <span className='inline-flex items-center'>
                        {sortDirection === 'asc' ? (
                          <ArrowUp className='h-3.5 w-3.5' />
                        ) : sortDirection === 'desc' ? (
                          <ArrowDown className='h-3.5 w-3.5' />
                        ) : (
                          <ArrowUpDown className='h-3.5 w-3.5 opacity-40' />
                        )}
                      </span>
                    )}
                  </button>

                  {showFilter && (
                    <ColumnFilter column={header.column} config={filterConfig} labels={labels} />
                  )}
                </div>

                {header.column.getCanResize() && (
                  <div
                    onMouseDown={header.getResizeHandler()}
                    onTouchStart={header.getResizeHandler()}
                    className={cn(
                      'absolute right-0 top-0 h-full w-2 cursor-col-resize select-none touch-none',
                      'before:absolute before:left-1/2 before:top-0 before:h-full before:w-px',
                      'before:bg-border/50 before:transform before:-translate-x-1/2 before:transition-colors',
                      'hover:before:bg-primary',
                      header.column.getIsResizing() && 'before:bg-primary'
                    )}
                    style={{ transform: 'translateX(50%)' }}
                    aria-hidden='true'
                  />
                )}
              </th>
            );

            return enableHeaderContextMenu && headerContextMenuItems ? (
              <HeaderContextMenu key={header.id} column={header.column} items={headerContextMenuItems}>
                {headerContent}
              </HeaderContextMenu>
            ) : (
              <React.Fragment key={header.id}>{headerContent}</React.Fragment>
            );
          })}
        </tr>
      ))}
    </thead>
  );
}

'use client';

import React, { useCallback, useEffect, useMemo, useRef } from 'react';
import { Cell, flexRender, Row } from '@tanstack/react-table';
import { useVirtualizer } from '@tanstack/react-virtual';
import { cn } from '../../lib/utils';
import { useDataGrid } from './context';
import { CellContextMenu } from './data-grid-context-menu';
import { EditableCell } from './data-grid-editable-cell';
import {
  CellEditConfig,
  CellRange,
  DataGridDensity,
  getPinningStyles,
  isInteractiveTarget,
  isMetaColumn,
  META_COLUMN_IDS,
  normalizeCellRange,
} from './types';

interface DataGridBodyProps {
  enableVirtualization?: boolean;
  estimateSize?: number;
}

const densityRowPaddingY: Record<DataGridDensity, string> = {
  compact: 'py-0.5',
  normal: 'py-1.5',
  comfortable: 'py-3',
};

export function DataGridBody({ enableVirtualization = false, estimateSize = 35 }: DataGridBodyProps) {
  const {
    table,
    isLoading,
    error,
    cellContextMenuItems,
    enableCellContextMenu,
    enableCellEditing,
    enableRowExpansion,
    renderExpandedRow,
    enableCellSelection,
    enableKeyboardNavigation,
    focusedCell,
    setFocusedCell,
    cellRange,
    setCellRange,
    rowClassName,
    onRowClick,
    onRowDoubleClick,
    density,
    loadingRowCount,
    emptyState,
    loadingState,
    errorState,
    labels,
    setEditingCell,
  } = useDataGrid();

  const tableContainerRef = useRef<HTMLTableSectionElement>(null);
  const rangeAnchorRef = useRef<{ rowIndex: number; colIndex: number } | null>(null);
  const isMouseDownRef = useRef(false);

  const rows = table.getRowModel().rows;
  const visibleColumns = table.getVisibleLeafColumns();
  const dataColumns = useMemo(
    () => visibleColumns.filter((c) => !isMetaColumn(c.id)),
    [visibleColumns]
  );

  const colSpan = visibleColumns.length;

  const colIndexMap = useMemo(() => {
    const map = new Map<string, number>();
    dataColumns.forEach((c, i) => map.set(c.id, i));
    return map;
  }, [dataColumns]);

  const colIndexById = useCallback((id: string) => colIndexMap.get(id) ?? -1, [colIndexMap]);

  // ---------------- Cell rendering ----------------

  const renderCellContent = (cell: Cell<any, unknown>) => {
    const column = cell.column;
    const row = cell.row;
    const value = cell.getValue();

    const columnDef = column.columnDef as any;
    const editConfig = columnDef.enableEditing;

    if (enableCellEditing && editConfig) {
      const config: CellEditConfig<any> =
        typeof editConfig === 'boolean' ? { enabled: true } : { enabled: true, ...editConfig };
      // Pre-render display content via flexRender (full TanStack context)
      const display = column.columnDef.cell
        ? flexRender(column.columnDef.cell, cell.getContext())
        : undefined;
      return (
        <EditableCell
          row={row}
          column={column}
          value={value}
          editConfig={config}
          displayContent={display}
        />
      );
    }

    return flexRender(column.columnDef.cell, cell.getContext());
  };

  // ---------------- Mouse range selection ----------------

  const beginRange = useCallback(
    (rowIndex: number, colIndex: number, extend: boolean) => {
      if (!enableCellSelection) return;
      if (!extend || !rangeAnchorRef.current) {
        rangeAnchorRef.current = { rowIndex, colIndex };
        setCellRange({
          startRowIndex: rowIndex,
          endRowIndex: rowIndex,
          startColIndex: colIndex,
          endColIndex: colIndex,
        });
      } else {
        const a = rangeAnchorRef.current;
        setCellRange({
          startRowIndex: a.rowIndex,
          endRowIndex: rowIndex,
          startColIndex: a.colIndex,
          endColIndex: colIndex,
        });
      }
    },
    [enableCellSelection, setCellRange]
  );

  const extendRange = useCallback(
    (rowIndex: number, colIndex: number) => {
      if (!enableCellSelection || !rangeAnchorRef.current) return;
      const a = rangeAnchorRef.current;
      setCellRange({
        startRowIndex: a.rowIndex,
        endRowIndex: rowIndex,
        startColIndex: a.colIndex,
        endColIndex: colIndex,
      });
    },
    [enableCellSelection, setCellRange]
  );

  const cellInRange = (rowIndex: number, colIndex: number, range: CellRange | null) => {
    if (!range) return false;
    const { r1, r2, c1, c2 } = normalizeCellRange(range);
    return rowIndex >= r1 && rowIndex <= r2 && colIndex >= c1 && colIndex <= c2;
  };

  // ---------------- Keyboard navigation ----------------

  const moveFocus = useCallback(
    (deltaRow: number, deltaCol: number, e: React.KeyboardEvent) => {
      if (!enableKeyboardNavigation || dataColumns.length === 0 || rows.length === 0) return;
      e.preventDefault();
      let rIdx = 0;
      let cIdx = 0;
      if (focusedCell) {
        const r = rows.findIndex((row) => row.id === focusedCell.rowId);
        const c = colIndexById(focusedCell.columnId);
        rIdx = r >= 0 ? r : 0;
        cIdx = c >= 0 ? c : 0;
      }
      const nextR = Math.max(0, Math.min(rows.length - 1, rIdx + deltaRow));
      const nextC = Math.max(0, Math.min(dataColumns.length - 1, cIdx + deltaCol));
      const nextRow = rows[nextR];
      const nextCol = dataColumns[nextC];
      setFocusedCell({ rowId: nextRow.id, columnId: nextCol.id });
      if (e.shiftKey && enableCellSelection) {
        if (!rangeAnchorRef.current) rangeAnchorRef.current = { rowIndex: rIdx, colIndex: cIdx };
        extendRange(nextR, nextC);
      } else {
        rangeAnchorRef.current = null;
        setCellRange(null);
      }
    },
    [
      enableKeyboardNavigation,
      enableCellSelection,
      dataColumns,
      rows,
      focusedCell,
      colIndexById,
      setFocusedCell,
      extendRange,
      setCellRange,
    ]
  );

  const handleCellKeyDown = useCallback(
    (e: React.KeyboardEvent, rowIndex: number, colIndex: number) => {
      if (!enableKeyboardNavigation) return;
      const row = rows[rowIndex];
      const col = dataColumns[colIndex];
      if (!row || !col) return;

      switch (e.key) {
        case 'ArrowDown':
          moveFocus(1, 0, e);
          return;
        case 'ArrowUp':
          moveFocus(-1, 0, e);
          return;
        case 'ArrowRight':
          moveFocus(0, 1, e);
          return;
        case 'ArrowLeft':
          moveFocus(0, -1, e);
          return;
        case 'Home':
          if (e.ctrlKey || e.metaKey) moveFocus(-rowIndex, -colIndex, e);
          else moveFocus(0, -colIndex, e);
          return;
        case 'End':
          if (e.ctrlKey || e.metaKey)
            moveFocus(rows.length - 1 - rowIndex, dataColumns.length - 1 - colIndex, e);
          else moveFocus(0, dataColumns.length - 1 - colIndex, e);
          return;
        case 'PageDown':
          moveFocus(10, 0, e);
          return;
        case 'PageUp':
          moveFocus(-10, 0, e);
          return;
        case ' ':
          if (table.options.enableRowSelection) {
            e.preventDefault();
            row.toggleSelected();
          }
          return;
        case 'Enter':
        case 'F2': {
          const editCfg = (col.columnDef as any).enableEditing;
          if (enableCellEditing && editCfg) {
            e.preventDefault();
            setEditingCell({ rowId: row.id, columnId: col.id });
          }
          return;
        }
        default:
          if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'a') {
            if (table.options.enableRowSelection) {
              e.preventDefault();
              table.toggleAllRowsSelected(true);
            }
            return;
          }
      }
    },
    [enableKeyboardNavigation, rows, dataColumns, moveFocus, table, enableCellEditing, setEditingCell]
  );

  // ---------------- Row click handlers ----------------

  const handleRowClick = (e: React.MouseEvent<HTMLTableRowElement>, row: Row<any>) => {
    if (isInteractiveTarget(e.target)) return;
    onRowClick?.(row, e);
  };
  const handleRowDoubleClick = (e: React.MouseEvent<HTMLTableRowElement>, row: Row<any>) => {
    if (isInteractiveTarget(e.target)) return;
    onRowDoubleClick?.(row, e);
  };

  // Row expansion + virtualization don't compose: expanded <tr>s aren't tracked in the
  // virtualizer's item count or measured into total size, so detail panels would either
  // overlap absolute rows or sit outside the scroll height.
  const effectiveVirtualization = enableVirtualization && !enableRowExpansion;

  const warnedExpansionConflictRef = useRef(false);
  useEffect(() => {
    if (
      import.meta.env.DEV &&
      enableVirtualization &&
      enableRowExpansion &&
      !warnedExpansionConflictRef.current
    ) {
      warnedExpansionConflictRef.current = true;
      // eslint-disable-next-line no-console
      console.warn(
        '[DataGrid] `enableVirtualization` is ignored when `enableRowExpansion` is enabled. ' +
          'Expanded detail rows are not yet measured by the row virtualizer; falling back to standard rendering.'
      );
    }
  }, [enableVirtualization, enableRowExpansion]);

  const rowVirtualizer = useVirtualizer({
    count: rows.length,
    getScrollElement: () => tableContainerRef.current,
    estimateSize: () => estimateSize,
    enabled: effectiveVirtualization && rows.length > 50,
  });

  // ---------------- Loading / error / empty states ----------------

  if (isLoading) {
    if (loadingState) {
      return (
        <tbody ref={tableContainerRef}>
          <tr>
            <td colSpan={colSpan} className='p-0'>
              {typeof loadingState === 'function' ? loadingState() : loadingState}
            </td>
          </tr>
        </tbody>
      );
    }
    // Default skeleton rows
    return (
      <tbody ref={tableContainerRef}>
        {Array.from({ length: loadingRowCount }).map((_, i) => (
          <tr key={`skeleton-${i}`} className='border-b border-border'>
            {visibleColumns.map((col) => (
              <td
                key={col.id}
                className={cn('px-3 align-middle text-sm border-r border-border/50', densityRowPaddingY[density])}>
                <div className='h-3.5 w-3/4 rounded bg-muted animate-pulse' />
              </td>
            ))}
          </tr>
        ))}
      </tbody>
    );
  }

  if (error) {
    return (
      <tbody ref={tableContainerRef}>
        <tr>
          <td colSpan={colSpan} className='h-24 text-center text-destructive'>
            {errorState
              ? typeof errorState === 'function'
                ? errorState(error)
                : errorState
              : labels.error(error)}
          </td>
        </tr>
      </tbody>
    );
  }

  if (rows.length === 0) {
    return (
      <tbody ref={tableContainerRef}>
        <tr>
          <td colSpan={colSpan} className='h-24 text-center text-muted-foreground'>
            {emptyState ? (typeof emptyState === 'function' ? emptyState() : emptyState) : labels.noData}
          </td>
        </tr>
      </tbody>
    );
  }

  const renderRow = (row: Row<any>, rowIndex: number, virtualStyle?: React.CSSProperties) => {
    const isSelected = row.getIsSelected();
    const isExpanded = enableRowExpansion && row.getIsExpanded();
    const customClass = typeof rowClassName === 'function' ? rowClassName(row) : rowClassName;

    return (
      <React.Fragment key={row.id}>
        <tr
          role='row'
          aria-rowindex={rowIndex + 2}
          aria-selected={isSelected}
          onClick={(e) => handleRowClick(e, row)}
          onDoubleClick={(e) => handleRowDoubleClick(e, row)}
          className={cn(
            'border-b border-border hover:bg-muted/50 transition-colors',
            isSelected && 'bg-accent/40 hover:bg-accent/40',
            (onRowClick || onRowDoubleClick) && 'cursor-pointer',
            customClass
          )}
          data-state={isSelected ? 'selected' : ''}
          style={virtualStyle}>
          {row.getVisibleCells().map((cell) => {
            const isDataCell = !isMetaColumn(cell.column.id);
            const colIndex = isDataCell ? colIndexById(cell.column.id) : -1;
            const isFocused =
              isDataCell && focusedCell?.rowId === row.id && focusedCell?.columnId === cell.column.id;
            const inRange = isDataCell && cellInRange(rowIndex, colIndex, cellRange);

            const tdContent = (
              <td
                role='gridcell'
                tabIndex={isDataCell && enableKeyboardNavigation ? (isFocused ? 0 : -1) : undefined}
                onFocus={() => {
                  if (isDataCell) setFocusedCell({ rowId: row.id, columnId: cell.column.id });
                }}
                onMouseDown={(e) => {
                  if (!isDataCell) return;
                  if (e.button !== 0) return;
                  isMouseDownRef.current = true;
                  beginRange(rowIndex, colIndex, e.shiftKey);
                  if (isDataCell && enableKeyboardNavigation) {
                    setFocusedCell({ rowId: row.id, columnId: cell.column.id });
                  }
                }}
                onMouseEnter={() => {
                  if (isMouseDownRef.current && isDataCell) extendRange(rowIndex, colIndex);
                }}
                onMouseUp={() => {
                  isMouseDownRef.current = false;
                }}
                onKeyDown={(e) => {
                  if (isDataCell) handleCellKeyDown(e, rowIndex, colIndex);
                }}
                className={cn(
                  'px-3 align-middle text-sm tabular-nums border-r border-border/50 [&:has([role=checkbox])]:pr-0 outline-none',
                  densityRowPaddingY[density],
                  cell.column.id === META_COLUMN_IDS.select && 'w-12 border-r-0',
                  cell.column.id === META_COLUMN_IDS.expand && 'w-9 border-r-0',
                  'has-[[data-editable-cell=true]]:hover:bg-muted/40 has-[[data-editable-cell=true]]:cursor-pointer',
                  inRange && 'bg-primary/10',
                  isFocused && enableKeyboardNavigation && 'ring-1 ring-primary/60 ring-inset'
                )}
                style={{
                  width: cell.column.getSize(),
                  minWidth: cell.column.columnDef.minSize ?? 50,
                  maxWidth: cell.column.columnDef.maxSize ?? 500,
                  ...getPinningStyles(cell.column, 1, 'var(--background)'),
                }}>
                {renderCellContent(cell)}
              </td>
            );

            if (enableCellContextMenu) {
              return (
                <CellContextMenu
                  key={cell.id}
                  row={row}
                  column={cell.column}
                  value={cell.getValue()}
                  items={cellContextMenuItems}>
                  {tdContent}
                </CellContextMenu>
              );
            }
            return <React.Fragment key={cell.id}>{tdContent}</React.Fragment>;
          })}
        </tr>

        {isExpanded && renderExpandedRow && (
          <tr key={`${row.id}-expanded`} className='border-b border-border bg-muted/20'>
            <td colSpan={colSpan} className='p-4'>
              {renderExpandedRow(row)}
            </td>
          </tr>
        )}
      </React.Fragment>
    );
  };

  const virtualItems = effectiveVirtualization ? rowVirtualizer.getVirtualItems() : [];
  if (virtualItems.length > 0) {
    return (
      <tbody
        ref={tableContainerRef}
        style={{ height: `${rowVirtualizer.getTotalSize()}px`, position: 'relative' }}
        onMouseUp={() => {
          isMouseDownRef.current = false;
        }}>
        {virtualItems.map((virtualItem) =>
          renderRow(rows[virtualItem.index], virtualItem.index, {
            position: 'absolute',
            top: 0,
            left: 0,
            width: '100%',
            height: `${virtualItem.size}px`,
            transform: `translateY(${virtualItem.start}px)`,
          })
        )}
      </tbody>
    );
  }

  return (
    <tbody
      ref={tableContainerRef}
      onMouseUp={() => {
        isMouseDownRef.current = false;
      }}>
      {rows.map((row, idx) => renderRow(row, idx))}
    </tbody>
  );
}

'use client';

import { ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight } from 'lucide-react';
import { Button } from '../ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../ui/select';
import { useDataGrid } from './context';

interface DataGridPaginationProps {
  pageSizeOptions?: number[];
}

export function DataGridPagination({ pageSizeOptions = [10, 20, 50, 100] }: DataGridPaginationProps) {
  const { table, labels } = useDataGrid();

  const currentPage = table.getState().pagination.pageIndex + 1;
  const totalPages = Math.max(1, table.getPageCount());
  const pageSize = table.getState().pagination.pageSize;

  const isServerSide = table.options.manualPagination;
  const totalCount = (table.options.meta as any)?.totalCount;
  const totalRows = isServerSide && totalCount != null ? totalCount : table.getFilteredRowModel().rows.length;
  const startRow = totalRows === 0 ? 0 : table.getState().pagination.pageIndex * pageSize + 1;
  const endRow = Math.min(startRow + pageSize - 1, totalRows);
  const selectedCount = table.getFilteredSelectedRowModel().rows.length;

  return (
    <div className='flex items-center justify-between px-2 flex-wrap gap-y-2'>
      <div className='flex-1 text-sm text-muted-foreground'>
        {selectedCount > 0 && <span>{labels.selected(selectedCount, totalRows)}</span>}
      </div>

      <div className='flex items-center space-x-6 lg:space-x-8'>
        <div className='flex items-center space-x-2'>
          <p className='text-sm font-medium'>{labels.rowsPerPage}</p>
          <Select value={pageSize.toString()} onValueChange={(value) => table.setPageSize(Number(value))}>
            <SelectTrigger className='h-8 w-[70px]'>
              <SelectValue placeholder={pageSize.toString()} />
            </SelectTrigger>
            <SelectContent side='top'>
              {pageSizeOptions.map((size) => (
                <SelectItem key={size} value={size.toString()}>
                  {size}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        <div className='flex w-[110px] items-center justify-center text-sm font-medium'>
          {labels.page(currentPage, totalPages)}
        </div>

        <div className='text-sm text-muted-foreground'>
          {totalRows > 0 ? labels.rowRange(startRow, endRow, totalRows) : '0 of 0'}
        </div>

        <div className='flex items-center space-x-2'>
          <Button
            variant='outline'
            className='hidden h-8 w-8 p-0 lg:flex'
            onClick={() => table.setPageIndex(0)}
            disabled={!table.getCanPreviousPage()}
            aria-label={labels.firstPage}>
            <ChevronsLeft className='h-4 w-4' />
          </Button>
          <Button
            variant='outline'
            className='h-8 w-8 p-0'
            onClick={() => table.previousPage()}
            disabled={!table.getCanPreviousPage()}
            aria-label={labels.previousPage}>
            <ChevronLeft className='h-4 w-4' />
          </Button>
          <Button
            variant='outline'
            className='h-8 w-8 p-0'
            onClick={() => table.nextPage()}
            disabled={!table.getCanNextPage()}
            aria-label={labels.nextPage}>
            <ChevronRight className='h-4 w-4' />
          </Button>
          <Button
            variant='outline'
            className='hidden h-8 w-8 p-0 lg:flex'
            onClick={() => table.setPageIndex(table.getPageCount() - 1)}
            disabled={!table.getCanNextPage()}
            aria-label={labels.lastPage}>
            <ChevronsRight className='h-4 w-4' />
          </Button>
        </div>
      </div>
    </div>
  );
}

'use client';

import { Search, Settings2, Eye, EyeOff, Rows3, Download } from 'lucide-react';
import { Input } from '../ui/input';
import { Button } from '../ui/button';
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '../ui/dropdown-menu';
import { useDataGrid } from './context';
import { DataGridDensity, isMetaColumn } from './types';
import { exportToCSV, exportToJSON } from './export-utils';
import { cn } from '../../lib/utils';

interface DataGridFiltersProps {
  enableGlobalFilter?: boolean;
  globalFilter: string;
  onGlobalFilterChange: (value: string) => void;
  enableDensityToggle?: boolean;
  density: DataGridDensity;
  onDensityChange: (density: DataGridDensity) => void;
  enableExport?: boolean;
  exportFileName?: string;
}

export function DataGridFilters({
  enableGlobalFilter = true,
  globalFilter,
  onGlobalFilterChange,
  enableDensityToggle = false,
  density,
  onDensityChange,
  enableExport = false,
  exportFileName,
}: DataGridFiltersProps) {
  const { table, labels, selectedRows } = useDataGrid();
  const fileBase = exportFileName ?? 'data-grid-export';

  return (
    <div className='flex items-center justify-between gap-2 flex-wrap'>
      <div className='flex flex-1 items-center space-x-2 min-w-0'>
        {enableGlobalFilter && (
          <div className='relative max-w-sm w-full'>
            <Search className='absolute left-2 top-2.5 h-4 w-4 text-muted-foreground' />
            <Input
              placeholder={labels.search}
              value={globalFilter}
              onChange={(e) => onGlobalFilterChange(e.target.value)}
              className='pl-8'
              aria-label={labels.search}
            />
          </div>
        )}
      </div>

      <div className='flex items-center gap-2'>
        {enableDensityToggle && (
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant='outline' size='sm' className='h-8' aria-label={labels.density}>
                <Rows3 className='mr-2 h-4 w-4' />
                {labels.density}
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align='end' className='w-[160px]'>
              <DensityItem current={density} value='compact' label={labels.densityCompact} onSelect={onDensityChange} />
              <DensityItem current={density} value='normal' label={labels.densityNormal} onSelect={onDensityChange} />
              <DensityItem
                current={density}
                value='comfortable'
                label={labels.densityComfortable}
                onSelect={onDensityChange}
              />
            </DropdownMenuContent>
          </DropdownMenu>
        )}

        {enableExport && (
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant='outline' size='sm' className='h-8' aria-label={labels.export}>
                <Download className='mr-2 h-4 w-4' />
                {labels.export}
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align='end' className='w-[180px]'>
              <DropdownMenuItem onClick={() => exportToCSV(table, { fileName: `${fileBase}.csv` })}>
                {labels.exportCsv}
              </DropdownMenuItem>
              <DropdownMenuItem onClick={() => exportToJSON(table, { fileName: `${fileBase}.json` })}>
                {labels.exportJson}
              </DropdownMenuItem>
              {selectedRows.length > 0 && (
                <>
                  <DropdownMenuSeparator />
                  <DropdownMenuItem
                    onClick={() =>
                      exportToCSV(table, { fileName: `${fileBase}-selected.csv`, selectedOnly: true })
                    }>
                    {labels.exportSelected} (CSV)
                  </DropdownMenuItem>
                </>
              )}
            </DropdownMenuContent>
          </DropdownMenu>
        )}

        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant='outline' size='sm' className='h-8' aria-label={labels.toggleColumns}>
              <Settings2 className='mr-2 h-4 w-4' />
              {labels.view}
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align='end' className='w-[180px]'>
            <DropdownMenuLabel>{labels.toggleColumns}</DropdownMenuLabel>
            <DropdownMenuSeparator />
            {table
              .getAllLeafColumns()
              .filter((column) => !isMetaColumn(column.id) && column.getCanHide())
              .map((column) => {
                const isVisible = column.getIsVisible();
                const headerLabel =
                  typeof column.columnDef.header === 'string' ? column.columnDef.header : column.id;
                return (
                  <DropdownMenuCheckboxItem
                    key={column.id}
                    className='capitalize'
                    checked={isVisible}
                    onCheckedChange={(value) => column.toggleVisibility(Boolean(value))}>
                    <div className='flex items-center space-x-2'>
                      {isVisible ? <Eye className='h-4 w-4' /> : <EyeOff className='h-4 w-4' />}
                      <span>{headerLabel}</span>
                    </div>
                  </DropdownMenuCheckboxItem>
                );
              })}
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    </div>
  );
}

function DensityItem({
