'use client';

import { X, MoreHorizontal } from 'lucide-react';
import { Button } from '../ui/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '../ui/dropdown-menu';
import { useDataGrid } from './context';
import { DataGridAction, DockOptions } from './types';
import { cn } from '../../lib/utils';

interface DataGridActionDockProps {
  dockOptions?: DockOptions;
}

export function DataGridActionDock({ dockOptions }: DataGridActionDockProps) {
  const { selectedRows, actions, table, labels } = useDataGrid();

  if (selectedRows.length === 0 || actions.length === 0) return null;

  const primaryCount = dockOptions?.primaryActionCount ?? 3;
  const position = dockOptions?.position ?? 'bottom';

  const visibleActions = actions.filter((action) => (action.isVisible ? action.isVisible(selectedRows) : true));
  const primaryActions = visibleActions.slice(0, primaryCount);
  const overflowActions = visibleActions.slice(primaryCount);

  const handleActionClick = async (action: DataGridAction<any>) => {
    try {
      await action.onClick(selectedRows);
    } catch (error) {
      console.error('Action failed:', error);
    }
  };

  const clearSelection = () => table.resetRowSelection();

  return (
    <div
      className={cn(
        'fixed left-1/2 -translate-x-1/2 z-50',
        position === 'bottom' ? 'bottom-4' : 'top-4'
      )}>
      <div className='flex items-center gap-2 px-3 py-2 bg-background border border-border rounded-md shadow-md'>
        <Button variant='ghost' size='sm' onClick={clearSelection} aria-label={labels.clearSelection} className='h-8 px-2'>
          {selectedRows.length} selected <X className='h-3 w-3 ml-1' />
        </Button>

        <div className='w-px h-4 bg-border' />

        <div className='flex items-center gap-1'>
          {primaryActions.map((action) => {
            const isEnabled = action.isEnabled ? action.isEnabled(selectedRows) : true;
            return (
              <Button
                key={action.id}
                variant={action.variant || 'default'}
                size='sm'
                onClick={() => handleActionClick(action)}
                disabled={!isEnabled}
                className='h-8 px-3'>
                {action.icon && <span className='h-3 w-3 mr-1'>{action.icon}</span>}
                <span className='text-xs'>{action.label}</span>
              </Button>
            );
          })}
        </div>

        {overflowActions.length > 0 && (
          <>
            <div className='w-px h-4 bg-border' />
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button variant='ghost' size='sm' className='h-8 px-2'>
                  <MoreHorizontal className='h-3 w-3 mr-1' />
                  <span className='text-xs'>{labels.more}</span>
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align='center' side={position === 'bottom' ? 'top' : 'bottom'} sideOffset={4}>
                {overflowActions.map((action) => {
                  const isEnabled = action.isEnabled ? action.isEnabled(selectedRows) : true;
                  return (
                    <DropdownMenuItem key={action.id} onClick={() => handleActionClick(action)} disabled={!isEnabled}>
                      {action.icon && <span className='h-3 w-3 mr-2'>{action.icon}</span>}
                      <span className='text-xs'>{action.label}</span>
                    </DropdownMenuItem>
                  );
                })}
              </DropdownMenuContent>
            </DropdownMenu>
          </>
        )}
      </div>
    </div>
  );
}

import { ReactNode } from 'react';
import {
  ContextMenu,
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuSeparator,
  ContextMenuTrigger,
} from '../ui/context-menu';
import { Row, Column } from '@tanstack/react-table';
import { CellContextMenuItem, HeaderContextMenuItem } from './types';

interface CellContextMenuProps<TData> {
  children: ReactNode;
  row: Row<TData>;
  column: Column<TData>;
  value: any;
  items?: CellContextMenuItem<TData>[];
}

interface HeaderContextMenuProps<TData> {
  children: ReactNode;
  column: Column<TData>;
  items?: HeaderContextMenuItem<TData>[];
}

export function CellContextMenu<TData>({ children, row, column, value, items = [] }: CellContextMenuProps<TData>) {
  if (items.length === 0) {
    return <>{children}</>;
  }

  const visibleItems = items.filter((item) => (item.isVisible ? item.isVisible(row, column, value) : true));

  if (visibleItems.length === 0) {
    return <>{children}</>;
  }

  return (
    <ContextMenu>
      <ContextMenuTrigger asChild>{children}</ContextMenuTrigger>
      <ContextMenuContent className='w-48'>
        {visibleItems.map((item) => {
          if (item.separator) {
            return <ContextMenuSeparator key={item.id} />;
          }

          const isEnabled = item.isEnabled ? item.isEnabled(row, column, value) : true;

          return (
            <ContextMenuItem
              key={item.id}
              onClick={() => item.onClick(row, column, value)}
              disabled={!isEnabled}
              className={`flex items-center gap-2 ${
                item.variant === 'destructive' ? 'text-destructive focus:text-destructive' : ''
              }`}>
              {item.icon && <span className='h-4 w-4'>{item.icon}</span>}
              <span>{item.label}</span>
            </ContextMenuItem>
          );
        })}
      </ContextMenuContent>
    </ContextMenu>
  );
}

export function HeaderContextMenu<TData>({ children, column, items = [] }: HeaderContextMenuProps<TData>) {
  if (items.length === 0) {
    return <>{children}</>;
  }

  const visibleItems = items.filter((item) => (item.isVisible ? item.isVisible(column) : true));

  if (visibleItems.length === 0) {
    return <>{children}</>;
  }

  return (
    <ContextMenu>
      <ContextMenuTrigger asChild>{children}</ContextMenuTrigger>
      <ContextMenuContent className='w-48'>
        {visibleItems.map((item) => {
          if (item.separator) {
            return <ContextMenuSeparator key={item.id} />;
          }

          const isEnabled = item.isEnabled ? item.isEnabled(column) : true;

          return (
            <ContextMenuItem
              key={item.id}
              onClick={() => item.onClick(column)}
              disabled={!isEnabled}
              className={`flex items-center gap-2 ${
                item.variant === 'destructive' ? 'text-destructive focus:text-destructive' : ''
              }`}>
              {item.icon && <span className='h-4 w-4'>{item.icon}</span>}
              <span>{item.label}</span>
            </ContextMenuItem>
          );
        })}
      </ContextMenuContent>
    </ContextMenu>
  );
}

'use client';

import React, { ReactNode, useCallback, useEffect, useRef, useState } from 'react';
import { Row, Column } from '@tanstack/react-table';
import { Input } from '../ui/input';
import { Button } from '../ui/button';
import { Check, X } from 'lucide-react';
import { cn } from '../../lib/utils';
import { CellEditConfig, CellEditComponentProps, EditBehaviors } from './types';
import { useDataGrid } from './context';

interface EditableCellProps<TData> {
  row: Row<TData>;
  column: Column<TData>;
  value: any;
  editConfig: CellEditConfig<TData>;
  /** Pre-rendered display content from the body (uses column.cell with full TanStack context) */
  displayContent?: ReactNode;
}

// Default text input — used when no custom component is provided
export function DefaultTextInput<TData>({
  value,
  onChange,
  onSave,
  onCancel,
  config,
  isSaving,
  error,
  placeholder,
  disabled,
  autoFocus = true,
  selectAllOnFocus = true,
}: CellEditComponentProps<TData, string>) {
  const [inputValue, setInputValue] = useState(String(value ?? ''));
  const inputRef = useRef<HTMLInputElement>(null);

  const behavior = config.behavior || EditBehaviors.clickToEdit;

  useEffect(() => {
    if (autoFocus && inputRef.current) {
      inputRef.current.focus();
      if (selectAllOnFocus) inputRef.current.select();
    }
  }, [autoFocus, selectAllOnFocus]);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && behavior.saveOn?.includes('enter')) {
      e.preventDefault();
      onChange(inputValue);
      onSave();
    } else if (e.key === 'Escape' && behavior.cancelOn?.includes('escape')) {
      e.preventDefault();
      onCancel();
    }
  };

  const handleBlur = () => {
    if (behavior.saveOn?.includes('blur')) {
      onChange(inputValue);
      onSave();
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const next = e.target.value;
    setInputValue(next);
    onChange(next);
  };

  return (
    <div className='w-full relative'>
      <div className='absolute top-0 left-0 right-0 z-20'>
        <Input
          ref={inputRef}
          value={inputValue}
          onChange={handleChange}
          onKeyDown={handleKeyDown}
          onBlur={handleBlur}
          placeholder={placeholder}
          disabled={disabled || isSaving}
          className={cn(
            'h-8 text-sm border-primary shadow-md',
            error && 'border-destructive',
            isSaving && 'opacity-50'
          )}
          autoFocus={autoFocus}
        />
      </div>

      {behavior.showActionButtons && (
        <div
          className={cn(
            'absolute z-30 bg-background border border-border rounded-md shadow-lg p-1 flex items-center gap-1',
            behavior.buttonPosition === 'bottom-right' ? 'top-9 right-0' : 'top-0 right-0'
          )}>
          <Button
            size='sm'
            variant='ghost'
            className='h-7 w-7 p-0'
            onClick={() => {
              onChange(inputValue);
              onSave();
            }}
            disabled={isSaving}>
            <Check className='h-3 w-3' />
          </Button>
          <Button size='sm' variant='ghost' className='h-7 w-7 p-0' onClick={onCancel} disabled={isSaving}>
            <X className='h-3 w-3' />
          </Button>
        </div>
      )}

      {error && (
        <div className='absolute top-9 left-0 right-0 z-30 p-2 text-xs text-destructive bg-destructive/10 border border-destructive/20 rounded-md shadow-lg'>
          {error}
        </div>
      )}
    </div>
  );
}

export function EditableCell<TData>({ row, column, value, editConfig, displayContent }: EditableCellProps<TData>) {
  const {
    editingCell,
    setEditingCell,
    onCellEdit,
    onCellValueChange,
    onCellEditError,
    defaultEditMode,
  } = useDataGrid<TData>();

  const [draftValue, setDraftValue] = useState(value);
  const [error, setError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  const cellRef = useRef<HTMLDivElement>(null);

  const behavior = editConfig.behavior || EditBehaviors.clickToEdit;
  const mode = behavior.mode || defaultEditMode;

  const isEditing = editingCell?.rowId === row.id && editingCell?.columnId === column.id;

  // Sync external value updates when not editing
  useEffect(() => {
    if (!isEditing) setDraftValue(value);
  }, [value, isEditing]);

  const handleChange = useCallback((next: any) => setDraftValue(next), []);

  const restoreFocus = useCallback(() => {
    // Defer until DOM updates so the read-mode container exists
    Promise.resolve().then(() => cellRef.current?.focus());
  }, []);

  const handleSave = useCallback(async () => {
    if (isSaving) return;

    if (editConfig.validate) {
      const validationError = editConfig.validate(draftValue, row);
      if (validationError) {
        setError(validationError);
        return;
      }
    }

    setIsSaving(true);
    setError(null);

    try {
      const oldValue = value;

      // Column-specific save runs first if provided; otherwise the grid-level handler.
      const save = editConfig.onSave
        ? () => editConfig.onSave!(draftValue, row, column)
        : onCellEdit
        ? () => onCellEdit(draftValue, row, column, oldValue)
        : null;
      if (save) {
        const ok = await save();
        if (!ok) {
          setError('Failed to save changes');
          setIsSaving(false);
          return;
        }
      }

      // Notify consumer of the value change so they can update state immutably.
      // We deliberately do NOT mutate row.original here.
      onCellValueChange?.(row.id, column.id, oldValue, draftValue);

      setEditingCell(null);
      editConfig.onEditEnd?.(row, column);
      restoreFocus();
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Failed to save changes';
      setError(msg);
      onCellEditError?.(msg, row, column);
    } finally {
      setIsSaving(false);
    }
  }, [
    isSaving,
    editConfig,
    draftValue,
    row,
    column,
    value,
    onCellEdit,
    onCellValueChange,
    onCellEditError,
    setEditingCell,
    restoreFocus,
  ]);

  const handleCancel = useCallback(() => {
    setDraftValue(value);
    setError(null);
    editConfig.onCancel?.(row, column);
    setEditingCell(null);
    restoreFocus();
  }, [value, editConfig, row, column, setEditingCell, restoreFocus]);

  const handleExit = useCallback(() => {
    setEditingCell(null);
    setError(null);
    restoreFocus();
  }, [setEditingCell, restoreFocus]);

  const startEditing = useCallback(() => {
    if (editConfig.disabled?.(row)) return;
    setEditingCell({ rowId: row.id, columnId: column.id });
    setError(null);
    editConfig.onEditStart?.(row, column);
  }, [editConfig, row, column, setEditingCell]);

  const handleClick = useCallback(() => {
    if (mode === 'click' && !isEditing) startEditing();
  }, [mode, isEditing, startEditing]);

  const handleDoubleClick = useCallback(() => {
    if (mode === 'doubleClick' && !isEditing) startEditing();
  }, [mode, isEditing, startEditing]);

  if (isEditing) {
    const EditComponent = editConfig.component || DefaultTextInput;
    return (
      <div className='relative w-full h-full min-h-[32px]'>
        <EditComponent
          value={draftValue}
          onChange={handleChange}
          onSave={handleSave}
          onCancel={handleCancel}
          onExit={handleExit}
          row={row}
          column={column}
          config={editConfig}
          isSaving={isSaving}
          error={error}
          placeholder={editConfig.placeholder}
          disabled={editConfig.disabled?.(row)}
          autoFocus={behavior.autoFocus}
          selectAllOnFocus={behavior.selectAllOnFocus}
        />
      </div>
    );
  }

  // Display mode — use pre-rendered content from the body if provided, otherwise stringified value
  const content = displayContent !== undefined ? displayContent : String(value ?? '');
  const isDisabled = editConfig.disabled?.(row);

  return (
    <div
      ref={cellRef}
      tabIndex={-1}
      data-editable-cell={isDisabled ? 'disabled' : 'true'}
      className={cn(
        'w-full h-full flex items-center outline-none',
        !isDisabled && 'cursor-pointer',
        isDisabled && 'opacity-50 cursor-not-allowed'
      )}
      onClick={handleClick}
      onDoubleClick={handleDoubleClick}>
      {content}
    </div>
  );
}

import { createContext, useContext } from 'react';
import { DataGridContextValue } from './types';

export const DataGridContext = createContext<DataGridContextValue<any> | null>(null);

export function useDataGrid<TData>() {
  const context = useContext(DataGridContext) as DataGridContextValue<TData> | null;

  if (!context) {
    throw new Error('useDataGrid must be used within a DataGrid component');
  }

  return context;
}

import {
  Row,
  Table,
  Column,
  ColumnFiltersState,
  SortingState,
  VisibilityState,
  RowSelectionState,
  PaginationState,
  ColumnPinningState,
  ColumnSizingState,
  ColumnOrderState,
  ExpandedState,
  Updater,
} from '@tanstack/react-table';
import type { CSSProperties, ReactNode, ComponentType, MouseEvent as ReactMouseEvent } from 'react';

// ---------------- Meta columns (select / expand) ----------------

export const META_COLUMN_IDS = { select: 'select', expand: 'expand' } as const;
export type MetaColumnId = (typeof META_COLUMN_IDS)[keyof typeof META_COLUMN_IDS];
export function isMetaColumn(id: string): boolean {
  return id === META_COLUMN_IDS.select || id === META_COLUMN_IDS.expand;
}

// ---------------- Pinning style (shared by header + body cells) ----------------

export function getPinningStyles<TData>(
  column: Column<TData, unknown>,
  zIndex: number,
  background?: string
): CSSProperties {
  const pinned = column.getIsPinned();
  if (!pinned) return {};
  return {
    position: 'sticky',
    left: pinned === 'left' ? `${column.getStart('left')}px` : undefined,
    right: pinned === 'right' ? `${column.getAfter('right')}px` : undefined,
    zIndex,
    ...(background ? { background } : {}),
  };
}

// ---------------- Cell range helpers ----------------

export function normalizeCellRange(range: { startRowIndex: number; endRowIndex: number; startColIndex: number; endColIndex: number }) {
  return {
    r1: Math.min(range.startRowIndex, range.endRowIndex),
    r2: Math.max(range.startRowIndex, range.endRowIndex),
    c1: Math.min(range.startColIndex, range.endColIndex),
    c2: Math.max(range.startColIndex, range.endColIndex),
  };
}

// ---------------- Interactive target detection (row click guards) ----------------

const INTERACTIVE_TARGET_SELECTOR =
  'input, textarea, select, button, a, [role=checkbox], [role=menuitem], [data-row-action], [contenteditable=true]';

export function isInteractiveTarget(target: EventTarget | null): boolean {
  if (!(target instanceof HTMLElement)) return false;
  return !!target.closest(INTERACTIVE_TARGET_SELECTOR);
}

// ---------------- Cell editing ----------------

export type CellEditMode = 'click' | 'doubleClick';
export type CellEditTrigger = 'blur' | 'enter' | 'escape' | 'manual' | 'immediate';

export interface CellEditBehavior {
  mode?: CellEditMode;
  saveOn?: CellEditTrigger[];
  cancelOn?: CellEditTrigger[];
  showActionButtons?: boolean;
  buttonPosition?: 'top-right' | 'bottom-right';
  autoSave?: boolean;
  autoFocus?: boolean;
  selectAllOnFocus?: boolean;
}

export interface CellEditConfig<TData, TValue = any> {
  enabled: boolean;
  behavior?: CellEditBehavior;
  component?: ComponentType<CellEditComponentProps<TData, TValue>>;
  validate?: (value: TValue, row: Row<TData>) => string | null;
  onSave?: (value: TValue, row: Row<TData>, column: Column<TData>) => Promise<boolean> | boolean;
  onCancel?: (row: Row<TData>, column: Column<TData>) => void;
  onEditStart?: (row: Row<TData>, column: Column<TData>) => void;
  onEditEnd?: (row: Row<TData>, column: Column<TData>) => void;
  placeholder?: string;
  disabled?: (row: Row<TData>) => boolean;
}

export interface CellEditComponentProps<TData, TValue = any> {
  value: TValue;
  onChange: (value: TValue) => void;
  onSave: () => void;
  onCancel: () => void;
  onExit: () => void;
  row: Row<TData>;
  column: Column<TData>;
  config: CellEditConfig<TData, TValue>;
  isSaving: boolean;
  error: string | null;
  placeholder?: string;
  disabled?: boolean;
  autoFocus?: boolean;
  selectAllOnFocus?: boolean;
}

export interface QuickEditConfig<TData, TValue = any> {
  component?: ComponentType<CellEditComponentProps<TData, TValue>>;
  validate?: (value: TValue, row: Row<TData>) => string | null;
  onSave?: (value: TValue, row: Row<TData>, column: Column<TData>) => Promise<boolean> | boolean;
  placeholder?: string;
  disabled?: (row: Row<TData>) => boolean;
}

export const EditBehaviors = {
  clickToEdit: {
    mode: 'click' as CellEditMode,
    saveOn: ['blur', 'enter'] as CellEditTrigger[],
    cancelOn: ['escape'] as CellEditTrigger[],
    showActionButtons: false,
    autoFocus: true,
    selectAllOnFocus: true,
  },
  clickWithButtons: {
    mode: 'click' as CellEditMode,
    saveOn: ['manual'] as CellEditTrigger[],
    cancelOn: ['manual'] as CellEditTrigger[],
    showActionButtons: true,
    buttonPosition: 'top-right' as const,
    autoFocus: true,
    selectAllOnFocus: true,
  },
  doubleClickToEdit: {
    mode: 'doubleClick' as CellEditMode,
    saveOn: ['blur', 'enter'] as CellEditTrigger[],
    cancelOn: ['escape'] as CellEditTrigger[],
    showActionButtons: false,
    autoFocus: true,
    selectAllOnFocus: true,
  },
} as const;

